package br.com.livraria.book.controller;
import br.com.livraria.book.model.Book; import br.com.livraria.book.model.Categoria; import br.com.livraria.book.service.BookService; import br.com.livraria.book.service.CategoriaService;
import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.web.client.RestTemplate; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/book-service") public class BookController {private final BookService service; public BookController(BookService service){this.service=service;} @GetMapping public List<Book> listar(){return service.listar();} @GetMapping("/{id}") public Book buscar(@PathVariable Long id){return service.buscar(id);} @GetMapping("/{id}/{currency}") public Book buscarConvertido(@PathVariable Long id,@PathVariable String currency){return service.buscarConvertido(id,currency);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Book salvar(@RequestBody Map<String,Object> body){Book b=new Book();b.setAuthor((String)body.get("author"));b.setTitle((String)body.get("title"));b.setLaunchDate(java.time.LocalDate.parse((String)body.get("launchDate")));b.setPrice(Double.valueOf(body.get("price").toString()));return service.salvar(b,Long.valueOf(body.get("categoriaId").toString()));} @PutMapping("/{id}") public Book atualizar(@PathVariable Long id,@RequestBody Map<String,Object> body){Book b=new Book();b.setAuthor((String)body.get("author"));b.setTitle((String)body.get("title"));b.setLaunchDate(java.time.LocalDate.parse((String)body.get("launchDate")));b.setPrice(Double.valueOf(body.get("price").toString()));return service.atualizar(id,b,Long.valueOf(body.get("categoriaId").toString()));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void excluir(@PathVariable Long id){service.excluir(id);} }
@Configuration class RestTemplateConfiguration { @Bean RestTemplate restTemplate(){return new RestTemplate();} }
